//! Self-registering modules for build scripts.
//!
//! Central lists (`mod x;` lines, `v.extend(x::specs())` chains, `#[cfg(test)] mod tests_x;`) are
//! the files every feature branch edits, so parallel branches conflict on them. A crate's
//! `build.rs` describes a directory with [`Modules`]; the generated file (in `OUT_DIR`, `include!`d
//! by the parent module) declares one module per file and, optionally, a table of the modules that
//! define a conventional function. Adding a command or an effect is then adding a file.
//!
//! Rules, applied to the files of the directory:
//! - `x.rs` and `x/mod.rs` are module `x`, declared with the configured visibility, unless the
//!   parent file already declares `mod x` by hand (keep a hand-written line for a different
//!   visibility, a `#[cfg]`, a module whose submodules live in `x/` next to `x.rs`, or one that
//!   defines `#[macro_export]` macros: those can't be used by path from a macro-expanded module).
//! - `tests.rs`, `tests_*.rs` and `*_tests.rs` are private `#[cfg(test)]` modules.
//! - `lib.rs`, `main.rs` and `mod.rs` are never modules of their own directory.
//! - With [`Modules::registry`], every non-test module (hand-declared ones too) whose file has a
//!   top-level `fn <name>(` is listed, by file name, as `(name, module::func)`.
//!
//! Generation is deterministic (sorted by file name). The generated declarations use absolute
//! `#[path]`s; `cargo fmt` does not follow them, so `cargo xtask fmt` formats every source file.

#![deny(clippy::unwrap_used, clippy::expect_used, clippy::panic, clippy::unimplemented, clippy::todo, clippy::unreachable)]

use std::collections::BTreeSet;
use std::fmt::Write as _;
use std::path::{Path, PathBuf};

/// A directory of modules to declare and, optionally, register.
#[derive(Clone, Debug)]
pub struct Modules<'a> {
    dir: &'a str,
    parent: &'a str,
    out: &'a str,
    vis: &'a str,
    registry: Option<(&'a str, &'a str, &'a str)>,
}

/// One discovered module.
#[derive(Clone, Debug, PartialEq, Eq)]
pub struct Module {
    pub name: String,
    /// `x.rs` or `x/mod.rs`.
    pub file: PathBuf,
    /// Declared by hand in the parent file.
    pub manual: bool,
    /// A `#[cfg(test)]` module (`tests.rs`, `tests_*.rs`, `*_tests.rs`).
    pub test: bool,
    /// `x.rs` with submodules in `x/`.
    pub nested_dir: bool,
}

impl<'a> Modules<'a> {
    /// The modules of `dir` (relative to the crate, e.g. `src/commands`), included by `parent`
    /// (e.g. `src/commands/mod.rs`) with `include!(concat!(env!("OUT_DIR"), "/<out>"))`.
    pub fn new(dir: &'a str, parent: &'a str, out: &'a str) -> Self {
        Self { dir, parent, out, vis: "pub(crate)", registry: None }
    }

    /// Visibility of the generated (non-test) declarations: `pub`, `pub(crate)` (default) or `""`.
    pub fn visibility(mut self, vis: &'a str) -> Self {
        self.vis = vis;
        self
    }

    /// Also generate `pub(crate) const <name>: &[(&str, <ty>)]` listing `(file name, module::<func>)`
    /// for every module defining a top-level `fn <func>(`.
    pub fn registry(mut self, name: &'a str, func: &'a str, ty: &'a str) -> Self {
        self.registry = Some((name, func, ty));
        self
    }

    /// Generate into `OUT_DIR` from a build script (prints the `rerun-if-changed` lines).
    pub fn generate(&self) -> Result<(), String> {
        let manifest = std::env::var_os("CARGO_MANIFEST_DIR").ok_or("CARGO_MANIFEST_DIR is not set (run from build.rs)")?;
        let out_dir = std::env::var_os("OUT_DIR").ok_or("OUT_DIR is not set (run from build.rs)")?;
        let manifest = PathBuf::from(manifest);
        println!("cargo:rerun-if-changed={}", manifest.join(self.dir).display());
        println!("cargo:rerun-if-changed={}", manifest.join(self.parent).display());
        let code = self.render(&manifest)?;
        let out = PathBuf::from(out_dir).join(self.out);
        // Rewriting identical content would still bump the mtime; skip it.
        if std::fs::read_to_string(&out).ok().as_deref() == Some(code.as_str()) {
            return Ok(());
        }
        std::fs::write(&out, code).map_err(|e| format!("{}: {e}", out.display()))
    }

    /// The generated Rust source for the crate at `manifest_dir`.
    pub fn render(&self, manifest_dir: &Path) -> Result<String, String> {
        let dir = manifest_dir.join(self.dir);
        let parent = manifest_dir.join(self.parent);
        let modules = discover(&dir, &parent)?;
        let mut s = format!("// @generated by effectcraft-buildgen from `{}` (build.rs): one module per file. Do not edit.\n", self.dir);
        for m in modules.iter().filter(|m| !m.manual) {
            if m.nested_dir {
                return Err(format!(
                    "{}: `{}.rs` has submodules in `{}/`; declare `mod {};` by hand in {} (generated declarations can't host submodule directories)",
                    self.dir, m.name, m.name, m.name, self.parent
                ));
            }
            let path = format!("{:?}", m.file.display().to_string());
            if m.test {
                let _ = writeln!(s, "#[cfg(test)]\n#[path = {path}]\nmod {};", m.name);
            } else {
                let vis = if self.vis.is_empty() { String::new() } else { format!("{} ", self.vis) };
                let _ = writeln!(s, "#[path = {path}]\n{vis}mod {};", m.name);
            }
        }
        if let Some((name, func, ty)) = self.registry {
            let _ = writeln!(s, "\n/// The modules of `{}` that define `fn {func}()`, by file name.", self.dir);
            let _ = writeln!(s, "pub(crate) const {name}: &[(&str, {ty})] = &[");
            for m in modules.iter().filter(|m| !m.test) {
                let text = std::fs::read_to_string(&m.file).map_err(|e| format!("{}: {e}", m.file.display()))?;
                if defines_fn(&text, func) {
                    let _ = writeln!(s, "    ({:?}, {}::{func}),", m.name, m.name);
                }
            }
            s.push_str("];\n");
        }
        Ok(s)
    }
}

/// The modules of `dir` (whose module file is `parent`), sorted by name.
pub fn discover(dir: &Path, parent: &Path) -> Result<Vec<Module>, String> {
    let parent_text = std::fs::read_to_string(parent).map_err(|e| format!("{}: {e}", parent.display()))?;
    let manual = declared_modules(&parent_text);
    let entries = std::fs::read_dir(dir).map_err(|e| format!("{}: {e}", dir.display()))?;
    let mut files = BTreeSet::new();
    let mut dirs = BTreeSet::new();
    for entry in entries {
        let entry = entry.map_err(|e| format!("{}: {e}", dir.display()))?;
        let path = entry.path();
        let Some(name) = path.file_name().and_then(|n| n.to_str()).map(str::to_string) else { continue };
        if name.starts_with('.') {
            continue;
        }
        if path.is_dir() {
            dirs.insert(name);
        } else if let Some(stem) = name.strip_suffix(".rs") {
            files.insert(stem.to_string());
        }
    }
    let mut out = Vec::new();
    for stem in &files {
        if matches!(stem.as_str(), "lib" | "main" | "mod") || !is_ident(stem) {
            continue;
        }
        let nested_dir = dirs.contains(stem);
        out.push(Module { name: stem.clone(), file: dir.join(format!("{stem}.rs")), manual: manual.contains(stem), test: is_test(stem), nested_dir });
    }
    for d in &dirs {
        let file = dir.join(d).join("mod.rs");
        if files.contains(d) || !file.is_file() || !is_ident(d) {
            continue;
        }
        out.push(Module { name: d.clone(), file, manual: manual.contains(d), test: is_test(d), nested_dir: false });
    }
    out.sort_by(|a, b| a.name.cmp(&b.name));
    Ok(out)
}

/// Names of the modules `text` declares (`mod x;`, `pub(crate) mod x;`, `#[cfg(test)] mod x;`,
/// inline `mod x {`).
pub fn declared_modules(text: &str) -> BTreeSet<String> {
    let mut out = BTreeSet::new();
    for line in text.lines() {
        let mut l = line.trim_start();
        // Attributes on the same line.
        while l.starts_with("#[") {
            let Some(end) = l.find(']') else { break };
            l = l.get(end + 1..).unwrap_or("").trim_start();
        }
        for vis in ["pub(crate) ", "pub(super) ", "pub "] {
            if let Some(rest) = l.strip_prefix(vis) {
                l = rest.trim_start();
                break;
            }
        }
        let Some(rest) = l.strip_prefix("mod ") else { continue };
        let name: String = rest.trim_start().chars().take_while(|c| c.is_ascii_alphanumeric() || *c == '_').collect();
        if !name.is_empty() {
            out.insert(name);
        }
    }
    out
}

/// Whether `text` has a top-level (unindented) `fn <func>(`, optionally `pub` / `pub(crate)`.
pub fn defines_fn(text: &str, func: &str) -> bool {
    let sig = format!("fn {func}(");
    text.lines().any(|l| {
        let l = l.strip_prefix("pub(crate) ").or_else(|| l.strip_prefix("pub(super) ")).or_else(|| l.strip_prefix("pub ")).unwrap_or(l);
        l.starts_with(&sig)
    })
}

fn is_test(name: &str) -> bool {
    name == "tests" || name.starts_with("tests_") || name.ends_with("_tests")
}

fn is_ident(name: &str) -> bool {
    let mut chars = name.chars();
    chars.next().is_some_and(|c| c.is_ascii_alphabetic() || c == '_') && chars.all(|c| c.is_ascii_alphanumeric() || c == '_')
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn declared_modules_reads_every_form() {
        let text =
            "pub mod a;\nmod b;\npub(crate) mod c;\n#[cfg(test)]\nmod tests_d;\n#[cfg(test)] mod e;\n  mod inline {\n}\n// mod comment;\nuse x::mod_y;\n";
        let got: Vec<String> = declared_modules(text).into_iter().collect();
        assert_eq!(got, ["a", "b", "c", "e", "inline", "tests_d"]);
    }

    #[test]
    fn defines_fn_only_top_level() {
        assert!(defines_fn("pub fn specs() -> Vec<X> {", "specs"));
        assert!(defines_fn("pub(crate) fn specs() -> Vec<X> {", "specs"));
        assert!(defines_fn("fn specs() {", "specs"));
        assert!(!defines_fn("    pub fn specs() {", "specs"));
        assert!(!defines_fn("pub fn specs_more() {", "specs"));
    }

    #[test]
    fn generates_sorted_declarations_and_registry() {
        let dir = std::env::temp_dir().join(format!("ec-buildgen-{}", std::process::id()));
        let _ = std::fs::remove_dir_all(&dir);
        std::fs::create_dir_all(dir.join("src/sub")).unwrap();
        std::fs::create_dir_all(dir.join("src/shaders")).unwrap();
        std::fs::write(dir.join("src/lib.rs"), "pub mod kept;\n").unwrap();
        std::fs::write(dir.join("src/zeta.rs"), "pub fn specs() -> Vec<u8> { vec![] }\n").unwrap();
        std::fs::write(dir.join("src/alpha.rs"), "fn helper() {}\n").unwrap();
        std::fs::write(dir.join("src/kept.rs"), "pub(crate) fn specs() -> Vec<u8> { vec![] }\n").unwrap();
        std::fs::write(dir.join("src/sub/mod.rs"), "pub fn specs() -> Vec<u8> { vec![] }\n").unwrap();
        std::fs::write(dir.join("src/tests_x.rs"), "pub fn specs() {}\n").unwrap();
        let code = Modules::new("src", "src/lib.rs", "gen.rs").visibility("pub").registry("SPECS", "specs", "fn() -> Vec<u8>").render(&dir).unwrap();
        let decls: Vec<&str> = code.lines().filter(|l| l.contains("mod ")).collect();
        assert_eq!(decls, ["pub mod alpha;", "pub mod sub;", "mod tests_x;", "pub mod zeta;"]);
        assert!(code.contains("#[cfg(test)]\n#[path = "));
        assert!(code.contains("    (\"kept\", kept::specs),\n    (\"sub\", sub::specs),\n    (\"zeta\", zeta::specs),\n];"));
        // `x.rs` + `x/` can't be generated.
        std::fs::write(dir.join("src/shaders.rs"), "mod inner;\n").unwrap();
        assert!(Modules::new("src", "src/lib.rs", "gen.rs").render(&dir).unwrap_err().contains("declare `mod shaders;` by hand"));
        let _ = std::fs::remove_dir_all(&dir);
    }
}
